// half-even rounding check with BigDecimal-like via strings not needed; just confirm expected cents
function he(x){ // emulate half_even at 2 decimals
  const n=Math.round(x*100);
  // JS round is half-up for .5; do half-even manually
  const scaled=x*100;
  const floor=Math.floor(scaled);
  const diff=scaled-floor;
  let r;
  if(Math.abs(diff-0.5)<1e-9){ r=(floor%2===0)?floor:floor+1; }
  else r=Math.round(scaled);
  return (r/100).toFixed(2);
}
